import { mkdir, rm } from 'node:fs/promises'
import { dirname, join } from 'node:path'
import { renderPage } from './page'
import { DOCS_PAGES, renderDocsPage } from './docs'

const SRC = import.meta.dir
export const DEFAULT_OUT = join(SRC, '..', 'dist')

export interface SiteFiles {
  [path: `${string}.html`]: string
  'index.html': string
  'site.css': string
  'site.js': string
  /** The link-preview card, generated by `bun run capture:website-og`. */
  'og.png': Uint8Array<ArrayBuffer>
}

/** The tracked `ab dispatch` frame the hero and the preview card both render. */
export function heroFrameText(): Promise<string> {
  return Bun.file(join(SRC, 'hero-frame.txt')).text()
}

/** Everything the site is made of, as text. */
export async function buildFiles(): Promise<SiteFiles> {
  const bundle = await Bun.build({
    entrypoints: [join(SRC, 'client.ts')],
    minify: true,
    target: 'browser',
  })
  if (!bundle.success) throw new Error(bundle.logs.map(String).join('\n'))
  const [output] = bundle.outputs
  return {
    ...Object.fromEntries(DOCS_PAGES.map((page) => [page.file, renderDocsPage(page)])),
    'index.html': renderPage(),
    'site.css': await Bun.file(join(SRC, 'styles.css')).text(),
    'site.js': await (output as Bun.BuildArtifact).text(),
    'og.png': new Uint8Array(await Bun.file(join(SRC, 'og.png')).arrayBuffer()),
  }
}

export async function buildSite(outDir: string = DEFAULT_OUT): Promise<string> {
  const files = await buildFiles()
  await rm(outDir, { recursive: true, force: true })
  await mkdir(outDir, { recursive: true })
  for (const [name, content] of Object.entries(files)) {
    const destination = join(outDir, name)
    await mkdir(dirname(destination), { recursive: true })
    await Bun.write(destination, content)
  }
  return outDir
}

if (import.meta.main) {
  const out = await buildSite()
  console.log(`built the site into ${out}`)
}
